const inside = (poly, lng, lat) => {
  let hit = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [xi, yi] = poly[i];
    const [xj, yj] = poly[j];
    if (yi > lat !== yj > lat && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) hit = !hit;
  }
  return hit;
};

// Bounding boxes so most points skip most polygons.
const box = (poly) => {
  let a = Infinity;
  let b = -Infinity;
  let c = Infinity;
  let d = -Infinity;
  for (const [x, y] of poly) {
    a = Math.min(a, x);
    b = Math.max(b, x);
    c = Math.min(c, y);
    d = Math.max(d, y);
  }
  return [a, b, c, d];
};
const LAND_BOX = LAND.map(box);
const SEA_BOX = SEAS.map(box);

export function isLand(lat, lng) {
  if (lat < -66) return true; // Antarctica
  let on = false;
  for (let i = 0; i < LAND.length && !on; i++) {
    const [a, b, c, d] = LAND_BOX[i];
    if (lng >= a && lng <= b && lat >= c && lat <= d && inside(LAND[i], lng, lat)) on = true;
  }
  if (!on) return false;
  for (let i = 0; i < SEAS.length; i++) {
    const [a, b, c, d] = SEA_BOX[i];
    if (lng >= a && lng <= b && lat >= c && lat <= d && inside(SEAS[i], lng, lat)) return false;
  }
  return true;
}

const RAD = Math.PI / 180;

/** A lat, lng in degrees as a unit vector [x, y, z]. */
export const toVec = (lat, lng) => [Math.cos(lat * RAD) * Math.cos(lng * RAD), Math.cos(lat * RAD) * Math.sin(lng * RAD), Math.sin(lat * RAD)];

let cache = null;
/** Land dots, flat [x, y, z, x, y, z, ...], spaced `step` degrees apart. */
export function landDots(step = 2.5) {
  if (cache && cache.step === step) return cache.dots;
  const out = [];
  for (let lat = -84 + step / 2; lat < 84; lat += step) {
    const ring = Math.max(1, Math.round((360 * Math.cos(lat * RAD)) / step));
    const dl = 360 / ring;
    // stagger alternate rows so the dots sit in a soft hex pattern
    const off = (Math.round((lat + 84) / step) % 2) * dl * 0.5;
    for (let k = 0; k < ring; k++) {
      const lng = -180 + off + k * dl;
      if (isLand(lat, lng)) out.push(...toVec(lat, lng));
    }
  }
  cache = { step, dots: out };
  return out;
}

